  'suggestions.comprendre.2_revoir_preventif_equipement': { one: '<b>S2 · Rever a manutenção preventiva</b>: equipamento cuja gama acompanhada já teve uma visita; pelo menos {n} avaria da mesma causa no período, após a primeira visita. A examinar: a gama não diz que avarias previne.', other: '<b>S2 · Rever a manutenção preventiva</b>: equipamento cuja gama acompanhada já teve uma visita; pelo menos {n} avarias da mesma causa no período, após a primeira visita. A examinar: a gama não diz que avarias previne.' },
  'suggestions.comprendre.3_anomalies_repetees_gamme': '<b>S3 · Anomalias repetidas</b>: gama acompanhada com uma anomalia em pelo menos 2 das últimas 4 visitas.',
  'suggestions.comprendre.4_allonger_gamme_depuis_format_2': { one: '<b>S4 · Alargar uma gama</b>: gama acompanhada de um equipamento de criticidade B ou C (nunca A); pelo menos {n} visita seguida sem anomalia (contadas desde a passagem ao formato 2, em {date}), e nenhuma avaria do equipamento desde a primeira dessas visitas. As inspeções regulamentares nunca são sugeridas.', other: '<b>S4 · Alargar uma gama</b>: gama acompanhada de um equipamento de criticidade B ou C (nunca A); pelo menos {n} visitas seguidas sem anomalia (contadas desde a passagem ao formato 2, em {date}), e nenhuma avaria do equipamento desde a primeira dessas visitas. As inspeções regulamentares nunca são sugeridas.' },
  'suggestions.comprendre.4_allonger_gamme_gamme': { one: '<b>S4 · Alargar uma gama</b>: gama acompanhada de um equipamento de criticidade B ou C (nunca A); pelo menos {n} visita seguida sem anomalia, e nenhuma avaria do equipamento desde a primeira dessas visitas. As inspeções regulamentares nunca são sugeridas.', other: '<b>S4 · Alargar uma gama</b>: gama acompanhada de um equipamento de criticidade B ou C (nunca A); pelo menos {n} visitas seguidas sem anomalia, e nenhuma avaria do equipamento desde a primeira dessas visitas. As inspeções regulamentares nunca são sugeridas.' },
  'suggestions.comprendre.apres_decision_ignoree_traitee': '<b>Depois de uma decisão</b> (ignorada ou tratada), só contam os factos posteriores: a sugestão volta se atingirem novamente o limiar.',
  'suggestions.comprendre.comprendre_suggestions': 'Compreender as sugestões',
  'suggestions.comprendre.date_ot_fin_travaux': '<b>Data de uma OT</b>: fim dos trabalhos, senão encerramento técnico, senão criação.',
  'suggestions.comprendre.definitions': 'Definições',
  'suggestions.comprendre.equipement_suivi_actif_pas': '<b>Equipamento acompanhado</b>: ativo e não abatido. <b>Gama acompanhada</b>: ativa, por data ou por contador (nunca por limiar), de um equipamento acompanhado.',
  'suggestions.comprendre.intervalle_median_ecart_milieu': '<b>Intervalo mediano</b>: o intervalo do meio, em dias, entre duas avarias consecutivas (metade dos intervalos são mais curtos).',
  'suggestions.comprendre.ordre_cartes_2_3': 'Ordem dos cartões: S2, S3, S1 e depois S4; depois criticidade A, B, C; depois número de factos. Os limiares definem-se em Definições (secção «Sugestões de manutenção preventiva»).',
  'suggestions.comprendre.panne_meme_cause_ot': '<b>Avaria da mesma causa</b>: OT corretiva (imediata ou diferida) encerrada, com o mesmo código de causa (todas as causas, incluindo «Outra causa»).',
  'suggestions.comprendre.periode_derniers_mois_aujourd': { one: '<b>Período</b>: o último mês ({n}), de {debutFenetre} até hoje.', other: '<b>Período</b>: os últimos {n} meses, de {debutFenetre} até hoje.' },
  'suggestions.comprendre.prevo_modifie_jamais_gamme': '<b>O Prévo nunca altera uma gama sozinho.</b> Uma sugestão não escreve nada: é você que decide. «Criar a gama» e «Abrir a gama» levam aos ecrãs da manutenção preventiva; a sugestão é marcada como tratada quando cria ou altera a gama. «Ignorar…» pede um motivo. Cada decisão fica registada no registo (separador «Decisões»).',
  'suggestions.comprendre.quatre_regles': 'As quatro regras',
  'suggestions.comprendre.visite_ot_cloture_gamme': '<b>Visita</b>: OT encerrada de uma gama. <b>Anomalia</b>: caixa «anomalia constatada» assinalada, ou pedido de intervenção criado a partir da visita.',
